```
struct redisCommand *lookupCommandBySdsLogic(dict *commands, sds s) {
    int argc, j;
    sds *strings = sdssplitlen(s,sdslen(s),"|",1,&argc);           ->>>>>>>>>>> here
    if (strings == NULL)
        return NULL;
